import{z as S,x as p,o as s,c as d,q as E,j as l,D as r,d as t,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"TSO / LRO","description":"","frontmatter":{"title":"TSO / LRO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tso-lro.md","filePath":"cs/tso-lro.md","lastUpdated":1791413859000}'),A={name:"cs/tso-lro.md"};function B(O,a,T,m,c,h){const o=p("Mermaid");return s(),d("div",null,[a[2]||(a[2]=E('<h1 id="tso-lro" tabindex="-1">TSO / LRO <a class="header-anchor" href="#tso-lro" aria-label="Permalink to &quot;TSO / LRO&quot;">​</a></h1><div class="epigraph"><p>主机把大缓冲交给网卡切 MSS 段（TSO），接收侧把连续段粘回大缓冲（LRO/GRO）；省 CPU，不改 TCP 语义，但延迟与抓包会变。</p><footer>—— 据网卡卸载实践；Linux GRO 文档通识；RFC 9293 段大小对照整理</footer></div><p><a href="/cs/mss-clamping">MSS</a> 约束线上看见的段。<a href="/cs/diffserv-qos">上一课</a> 结束排队合同。缺口是<strong>主机卸载</strong>：TSO/GSO、LRO/GRO。本课结束 TCP 细节课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每 MSS 一次系统调用与协议处理，10G 上 PPS 打满 CPU。<a href="/cs/socket-api">套接字</a> 热路径要减访。TSO：栈交 64 KB，网卡按 MSS 切并算校验。GRO：收端合并再交协议。语义仍是字节流；抓包若在 GRO 后，看起来「巨段」，排障易误。延迟：合并等待可能加尾延迟，与 URLLC 目标冲突，可关。</p><p>不要把 TSO 写成巨帧：巨帧在链路上真大；TSO 在链路上仍是 MSS。</p><p><span class="marginnote">GSO 是软件切。校验卸载与 TSO 常一起开。本课不写驱动队列 API。</span></p><h3 id="线上仍是-mss" tabindex="-1">线上仍是 MSS <a class="header-anchor" href="#线上仍是-mss" aria-label="Permalink to &quot;线上仍是 MSS&quot;">​</a></h3><p>卸载省 CPU，不改语义。抓包在 GRO 后会看见巨段。延迟敏感路径可关合并。巨帧是另一件事。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：主机切 vs 网卡切 vs 巨帧。画：应用 write → TSO → 线 MSS → GRO → read。与令牌桶：一次 TSO 突发像大 \\(b\\)。</p>',11)),(s(),l(n,null,{default:r(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%A4%A7%20write%22%5D%20--%3E%20TSO%5B%22%E7%BD%91%E5%8D%A1%E6%8C%89%20MSS%20%E5%88%87%22%5D%0A%20%20TSO%20--%3E%20WIRE%5B%22%E7%BA%BF%E4%B8%8A%E4%BB%8D%E6%98%AF%E6%AE%B5%22%5D%0A%20%20WIRE%20--%3E%20GRO%5B%22%E6%94%B6%E7%AB%AF%E5%90%88%E5%B9%B6%22%5D%0A%20%20GRO%20--%3E%20SOCK%5B%22%E5%A5%97%E6%8E%A5%E5%AD%97%E7%BC%93%E5%86%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"窗口、SACK、ECN 在段级；卸载必须正确复制时间戳与标志。虚拟化 virtio 也有 TSO，接 OS 课。RoCE 不走 TSO，走自己的 WQE。QUIC 常在用户态 GSO。",-1)),a[5]||(a[5]=e("p",null,"安全：错误卸载可造坏校验，中间盒若信卸载会放过。",-1)),a[6]||(a[6]=e("p",null,"一个大缓冲变成多个合法段，网卡要替栈补齐哪些逐段字段：",-1)),(s(),l(n,null,{default:r(()=>[i(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SKB%5B%2264%20KB%20%E5%A4%A7%E7%BC%93%E5%86%B2%22%5D%20--%3E%20SEG%5B%22%E7%BD%91%E5%8D%A1%E6%8C%89%20MSS%20%E5%88%87%E6%88%90%20N%20%E6%AE%B5%22%5D%0A%20%20SEG%20--%3E%20F1%5B%22%E6%AF%8F%E6%AE%B5%E9%87%8D%E7%AE%97%20TCP%20%E6%A0%A1%E9%AA%8C%E5%92%8C%22%5D%0A%20%20SEG%20--%3E%20F2%5B%22%E6%AF%8F%E6%AE%B5%E5%86%99%E8%87%AA%E5%B7%B1%E7%9A%84%20seq%20%E5%8F%B7%22%5D%0A%20%20SEG%20--%3E%20F3%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E4%B8%8E%E6%A0%87%E5%BF%97%E9%80%90%E6%AE%B5%E5%A4%8D%E5%88%B6%22%5D%0A%20%20F1%20--%3E%20OUT%5B%22%E9%80%90%E6%AE%B5%E4%B8%8A%E7%BA%BF%2C%20%E6%AF%8F%E6%AE%B5%20%E2%89%A4%20MSS%22%5D%0A%20%20F2%20--%3E%20OUT%0A%20%20F3%20--%3E%20OUT%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">数字实例：MSS = 1460 字节时，一次 64 KB 的 write（65536 字节）被切成 \\(\\lceil 65536/1460\\rceil \\approx 45\\) 个段。没有 TSO，栈要为每段各过一遍协议处理；开了 TSO 只走一次大缓冲路径，切与校验都下沉到网卡。</span></p><p><span class="marginnote">常见误区：抓包看到 60 KB 的「巨段」就以为链路在跑巨帧——其实抓包点落在 GRO 合并<strong>之后</strong>。线上每个以太网帧仍不超过 MSS。排障时先 <code>ethtool -k</code> 查卸载开关，必要时临时 <code>gro off</code> 对照再下结论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 XDP 的全部。MPTCP 是下一课序第一课。后课默认：TSO/GRO 是 CPU 优化，线语义仍是 MSS 段。</p><p>关卸载排障是合法手段，不是永久性能方案。</p><p><span class="marginnote">直觉类比：TSO 像「一次写好 45 封信的内容，盖章装封交给邮差分件投递」——投递颗粒度（每封信的尺寸）不变，省的是你自己重复写 45 个信封、贴 45 张邮票的工夫。</span></p><p>下一课<a href="/cs/mptcp">MPTCP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TSO 切发送，GRO 合并接收。</li><li>线上仍 MSS；巨帧是另一件事。</li><li>影响突发、延迟与抓包观感。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293 对照；网卡卸载实践。</li></ul>',9))])}const P=S(A,[["render",B]]);export{C as __pageData,P as default};
